//! The regions of a text that a tool writes between two marker comments, and the runs of the lines a change made
//! inside them (`RunKind::Generated`): a generator of Bazel files writes the rules of a module from its `.iml`
//! between ``### auto-generated section `build intellij.platform.core` start`` and ``… end``, and the hand-written
//! code around them is the code a person keeps. Inside such a region the source is what a reader reads, in its own
//! file, so a line that changed there is quiet; a marker that changed and every line outside are read.
//!
//! - **A marker** is a comment line (its first non-blank characters a comment leader: `#`, `//`, `--`, `;`, `<!--`,
//!   `/*`, `*`) whose words, case aside, hold `generated` as a word or a part of one (`auto-generated`,
//!   `autogenerated`, `@generated`) and whose last word, after a comment closer (`-->`, `*/`), is `start` or `begin`
//!   for the start of a region and `end` for its end. No name of an organisation or of a tool: the shape of the line
//!   alone.
//! - **A region** is an end with the nearest open start whose line is the same but for that last word; its name is
//!   the text between the leader and the last word, as written. An end without such a start and a start no end
//!   closes make no region; nor do a start and its end with another start between them, nor any region between
//!   them: nested regions are none. So the regions of a text never overlap.
//! - **Runs** (`generated_runs`): the part of a block whose old lines lie strictly between the markers of a region of
//!   the old text and whose new lines lie strictly between the markers of a region of the same name of the new text.
//!   A side of such a run may have no lines: a line added to a region or removed from one is the most common change,
//!   and the only kind of run whose block may have a side of no lines. A region on one side alone (added, removed,
//!   renamed) has no run. Pure text: a pair of no grammar has them too.
//! - **Precedence** (`with_generated`): a run of generated lines takes its lines; a run of another kind that shares a
//!   line with it, or stands across it on either side, is dropped whole, since a part of a run is not proven by
//!   itself (the tokens of the whole run are the same on both sides, not those of a part).

use line_diff::model::{BlockKind, DiffBlock, LineRun, RunKind};
use std::ops::Range;

/// A region a tool writes: its markers are the lines `start` and `end` (0-based, as the diff counts lines), its lines
/// those strictly between them
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GeneratedRegion {
    /// The text between the comment leader and the last word of its markers, trimmed, as written:
    /// ``auto-generated section `build intellij.platform.core` ``
    pub name: String,
    /// The 0-based line of its start marker
    pub start: u32,
    /// The 0-based line of its end marker
    pub end: u32,
}

impl GeneratedRegion {
    /// Whether the 0-based `line` lies strictly between its markers
    pub const fn holds(&self, line: u32) -> bool {
        self.start < line && line < self.end
    }

    /// The places of a side of a block that its region holds: the lines strictly between its markers, as a range
    /// whose ends run from the line after the start marker to the end marker. A side of no lines at `p` (lines
    /// inserted before line `p`, or removed from there) is inside when `start < p && p <= end`: the place lies
    /// between the markers
    const fn inside(&self) -> Range<u32> {
        self.start + 1..self.end
    }
}

/// The region of `regions` (by `start`, without overlap, as `generated_regions` gives them) that holds the 0-based
/// `line` strictly between its markers, if one does: a binary search
pub fn region_of(regions: &[GeneratedRegion], line: u32) -> Option<&GeneratedRegion> {
    let after = regions.partition_point(|region| region.start < line);
    after.checked_sub(1).map(|before| &regions[before]).filter(|region| region.holds(line))
}

/// The regions a tool writes in the lines `lines` of a side (without their line ends), by their start, without
/// overlap. The caller splits the text as its diff does (`line_diff::text_lines::TextLines`: `\n`, `\r\n` and a lone
/// `\r` end a line), so the lines of a region are the lines of the blocks
pub fn generated_regions(lines: &[&str]) -> Vec<GeneratedRegion> {
    struct Open<'t> {
        line: u32,
        key: &'t str,
        name: &'t str,
        /// Another start opened after it
        nested: bool,
    }
    let mut regions = Vec::new();
    let mut open: Vec<Open<'_>> = Vec::new();
    for (number, line) in (0u32..).zip(lines.iter().copied()) {
        let Some(marker) = marker_of(line) else { continue };
        match marker.edge {
            Edge::Start => {
                for outer in &mut open {
                    outer.nested = true;
                }
                open.push(Open { line: number, key: marker.key, name: marker.name, nested: false });
            }
            Edge::End => {
                if let Some(at) = open.iter().rposition(|start| start.key == marker.key) {
                    let start = &open[at];
                    if start.nested {
                        // the regions inside it are nested in it: none of them is one
                        regions.truncate(regions.partition_point(|region: &GeneratedRegion| region.start < start.line));
                    } else {
                        regions.push(GeneratedRegion { name: start.name.to_string(), start: start.line, end: number });
                    }
                    // the starts after it are closed by none
                    open.truncate(at);
                }
            }
        }
    }
    regions
}

/// Which marker a line is
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Edge {
    Start,
    End,
}

/// A marker line
struct Marker<'t> {
    edge: Edge,
    /// The line without its last word and its comment closer, trimmed: what a start and its end share
    key: &'t str,
    /// The key without its comment leader, trimmed
    name: &'t str,
}

/// The comment leaders a marker starts with, the longer one of a common start first
const LEADERS: [&str; 7] = ["<!--", "/*", "//", "--", "#", ";", "*"];
/// The comment closers a marker may end with
const CLOSERS: [&str; 2] = ["-->", "*/"];

/// The marker `line` is, if it is one
fn marker_of(line: &str) -> Option<Marker<'_>> {
    let trimmed = line.trim();
    let leader = LEADERS.iter().find(|leader| trimmed.starts_with(**leader))?;
    let body = CLOSERS.iter().find_map(|closer| trimmed.strip_suffix(closer)).unwrap_or(trimmed).trim_end();
    let at = body.rfind(char::is_whitespace)?;
    let (key, last) = (body[..at].trim_end(), body[at..].trim_start());
    let edge = if last.eq_ignore_ascii_case("start") || last.eq_ignore_ascii_case("begin") {
        Edge::Start
    } else if last.eq_ignore_ascii_case("end") {
        Edge::End
    } else {
        return None;
    };
    // the leader and its repeats (`###`, `///`, `/**`), then the text up to the last word
    let leader_chars: Vec<char> = leader.chars().collect();
    let name = key.get(leader.len()..)?.trim_start_matches(|c: char| leader_chars.contains(&c)).trim();
    if name.is_empty() || !holds_generated(name) {
        return None;
    }
    Some(Marker { edge, key, name })
}

/// Whether `text` holds `generated`, case aside, as a word or a part of one
fn holds_generated(text: &str) -> bool {
    const WORD: &[u8] = b"generated";
    text.as_bytes().windows(WORD.len()).any(|window| window.eq_ignore_ascii_case(WORD))
}

/// The runs of the lines `blocks` changed inside the regions a tool writes (`RunKind::Generated`, quiet), by
/// `old_start`, each inside one block, in the order of both sides, from the regions of the old text and of the new
/// one (`generated_regions`): in each block that is not `Ignored`, the part of its old lines inside a region of the
/// old text paired with the part of its new lines inside a region of the same name of the new text, a side of such a
/// part maybe of no lines, never both. A marker is in no run
pub fn generated_runs(blocks: &[DiffBlock], old: &[GeneratedRegion], new: &[GeneratedRegion]) -> Vec<LineRun> {
    let mut runs = Vec::new();
    if old.is_empty() || new.is_empty() {
        return runs;
    }
    for block in blocks.iter().filter(|block| block.kind != BlockKind::Ignored) {
        let (old_lines, new_lines) = (block.old_start..block.old_end, block.new_start..block.new_end);
        let (mut old_from, mut new_from) = (old_lines.start, new_lines.start);
        for old_region in near(old, &old_lines) {
            let Some(old_part) = part(&old_lines, old_region) else { continue };
            for new_region in near(new, &new_lines).filter(|region| region.name == old_region.name) {
                let Some(new_part) = part(&new_lines, new_region) else { continue };
                if (old_part.is_empty() && new_part.is_empty())
                    || old_part.start < old_from
                    || new_part.start < new_from
                {
                    continue;
                }
                (old_from, new_from) = (old_part.end, new_part.end);
                runs.push(LineRun {
                    old_start: old_part.start,
                    old_end: old_part.end,
                    new_start: new_part.start,
                    new_end: new_part.end,
                    kind: RunKind::Generated,
                    quiet: true,
                });
                break;
            }
        }
    }
    runs
}

/// The regions of `regions` (by `start`, without overlap) whose places may meet `lines`
fn near<'r>(regions: &'r [GeneratedRegion], lines: &Range<u32>) -> impl Iterator<Item = &'r GeneratedRegion> {
    // a region that ends before the lines start holds none of their places
    let from = regions.partition_point(|region| region.end < lines.start);
    regions[from..].iter().take_while(move |region| region.start < lines.end)
}

/// The part of the side `lines` of a block that `region` holds: its lines strictly between the markers, or the place
/// of no lines where the side meets the inside of the region without a line in it: a side of no lines at `p` with
/// `start < p <= end` (the rule Branch Deck's review reads such a side by too), or the lines of a side that end at the
/// line after the start marker or start at the end marker. `None` where they do not meet
fn part(lines: &Range<u32>, region: &GeneratedRegion) -> Option<Range<u32>> {
    let inside = region.inside();
    let (start, end) = (lines.start.max(inside.start), lines.end.min(inside.end));
    (start <= end).then_some(start..end)
}

/// `runs` (by `old_start`, each inside one block, without overlap) with the runs of generated lines `generated` (as
/// `generated_runs` gives them): a run of `runs` that neither ends before a run of generated lines nor starts after
/// it, on both sides, is dropped whole, and the generated ones take its place. In the order of both sides
pub fn with_generated(runs: Vec<LineRun>, generated: Vec<LineRun>) -> Vec<LineRun> {
    if generated.is_empty() {
        return runs;
    }
    let mut merged: Vec<LineRun> = runs.into_iter().filter(|run| apart_from_generated(run, &generated)).collect();
    merged.extend(generated);
    // two runs in order on both sides with the same `old_start`: the first has no old lines, so its new ones come first
    merged.sort_unstable_by_key(|run| (run.old_start, run.new_start));
    merged
}

/// Whether `run` ends before each run of `generated` starts or starts after it ends, on both sides: whether it keeps
/// its lines beside them (`with_generated`)
pub fn apart_from_generated(run: &LineRun, generated: &[LineRun]) -> bool {
    generated.iter().all(|taken| precedes(run, taken) || precedes(taken, run))
}

/// Whether `first` ends before `second` starts, on both sides
const fn precedes(first: &LineRun, second: &LineRun) -> bool {
    first.old_end <= second.old_start && first.new_end <= second.new_start
}
